import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's periods: each uniquely named on the sheet, none overlapping another. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final Rollup rollup;
    private final RoleService roles;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, Rollup rollup, RoleService roles,
            Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.roles = roles;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        String n = name.trim();
        if (from.isAfter(to)) {
            throw new PeriodRefusedException("The from-date must be on or before the to-date.");
        }
        if (cap != null && cap < 1) {
            throw new PeriodRefusedException("The cap must be a whole number of 1 or more.");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(n))) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        existing.stream().filter(p -> p.overlaps(from, to)).findFirst().ifPresent(p -> {
            throw new PeriodRefusedException("The period overlaps " + p.getName() + ".");
        });
        Period period;
        try {
            period = periods.saveAndFlush(new Period(sheetId, n, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                + " period=" + n + " from=" + from + " to=" + to + (cap != null ? " cap=" + cap : ""));
        return period;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month, each from
     *  the first to the last day of its month and named yyyy-mm; a month whose name is taken or whose days
     *  overlap a period on the sheet is left out. A blank from-date takes the sheet's today. Refused when
     *  the to-date is before the from-date. The periods made, in order. */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate start = from == null ? sheet.getToday() : from;
        if (to.isBefore(start)) {
            throw new PeriodRefusedException("The to-date must be on or after the from-date.");
        }
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth m = YearMonth.from(start); !m.isAfter(YearMonth.from(to)); m = m.plusMonths(1)) {
            String name = m.toString();
            LocalDate first = m.atDay(1);
            LocalDate last = m.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(name) || p.overlaps(first, last))) {
                continue;
            }
            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(period);
            made.add(period);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                    + " period=" + name + " from=" + first + " to=" + last);
        }
        return made;
    }

    /** Generate the twelve monthly periods of a fiscal year, exactly as {@link #generate} does from the
     *  first month of the year to its last: the fiscal year starts on the first day of the sheet's fiscal
     *  start month in the year it is named by. The periods made, in order. */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        // Locking the sheet first reads the fiscal start month as it stands while the periods are made.
        Sheet sheet = sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate first = LocalDate.of(year, sheet.getFiscalStartMonth(), 1);
        return generate(sheetId, user, first, first.plusYears(1).minusDays(1));
    }

    /** Close a period, fixing each person's due-total and carried figure for it and its own as it is now; refused when the user's role may not
     *  close it, or it is already closed. A soft-closed period can be closed, fixing its figures afresh. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        // Locking the sheet makes the close and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "close");
        if (period.isClosed()) {
            throw new PeriodRefusedException("The period is already closed.");
        }
        return closeNow(sheetId, user, period, false);
    }

    /** Soft-close a period, fixing each person's due-total and carried figure for it and its own as it is now while its claims
     *  can still change; refused when the user's role may not close it, or it is already closed or
     *  soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        // Locking the sheet makes the soft close and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "close");
        if (period.isClosed() || period.isSoftClosed()) {
            throw new PeriodRefusedException("The period is already closed.");
        }
        period.softClose(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
        periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + period.getClosedTotal().toPlainString());
        return period;
    }

    /** Close, in order of their to-dates, every open period whose to-date plus the grace days is before the
     *  sheet's (new) today, each as a close by hand would (a soft-closed period keeps its fixed figures); none
     *  when the grace days are off. The caller holds the sheet's lock. */
    @Transactional
    public void closeOverdue(String sheetId, String user, LocalDate today, Integer graceDays) {
        if (graceDays == null) {
            return;
        }
        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeNow(sheetId, user, p, true));
    }

    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
        period.close(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()),
                rollup.carriedByPerson(sheetId, period, periods.findBySheetIdOrderByFromDateAsc(sheetId)));
        periods.saveAndFlush(period);
        BigDecimal total = period.getClosedTotal();
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
        return period;
    }

    /** Reopen a closed or soft-closed period, making its due-total and each person's carried figure live again; by a role the sheet allows (a steward
     *  by the standing rule), and refused when it is open. */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        // Locking the sheet makes the reopen and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        roles.require(sheetId, user, "reopen");
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new PeriodRefusedException("The period is not closed.");
        }
        period.reopen();
        periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + period.getName());
        return period;
    }
}
    if (capText && !/^[0-9]+$/.test(capText)) return 'Enter the cap as a whole number, or leave it blank.';
    const cap = capText ? Number(capText) : null;
    if (cap !== null && cap < 1) return 'The cap must be 1 or more.';
    if (this.periods().some((p) => p.name.toLowerCase() === name.toLowerCase())) return 'That period name is already in use.';
    const clash = this.periods().find((p) => p.from <= to && from <= p.to);
    if (clash) return `The period overlaps ${clash.name}.`;
    const sid = this.session.sheetId()!;
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(this.url(sid), { name, from, to, cap }, { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => [...ps, period].sort(byFrom));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        return 'The period overlaps another, or its name is already in use.';
      }
      if (e instanceof HttpErrorResponse && e.status === 400) {
        return 'Enter a name, the from and to dates as YYYY-MM-DD, and a cap of 1 or more (or none).';
      }
      return e instanceof HttpErrorResponse ? `Could not add period (${e.status}).` : 'Could not add period.';
    }
  }

  /** Generate a period per calendar month from the from-date's month to the to-date's month (a blank
   *  from-date takes the sheet's today), leaving out any month whose name is taken or that overlaps a
   *  period: how many were made, or an error message when refused. */
  async generate(fromDate: string, toDate: string): Promise<number | string> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    const from = fromDate.trim() || this.session.today() || '';
    const to = toDate.trim();
    if (!isDate(from) || !isDate(to)) return 'Enter the from and to dates as YYYY-MM-DD.';
    if (to < from) return 'The to-date must be on or after the from-date.';
    const sid = this.session.sheetId()!;
    try {
      const made = await firstValueFrom(
        this.http.post<Period[]>(`${this.url(sid)}/generate`, { from, to }, { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => [...ps, ...made].sort(byFrom));
      return made.length;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not add periods.';
      if (e instanceof HttpErrorResponse && e.status === 409) return 'The to-date must be on or after the from-date.';
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter the from and to dates as YYYY-MM-DD.';
      return e instanceof HttpErrorResponse ? `Could not generate periods (${e.status}).` : 'Could not generate periods.';
    }
  }

  /** Generate the twelve monthly periods of a fiscal year (named by the calendar year its first day falls
   *  in) as the generator does: how many were made, or an error message when refused. */
  async generateFiscalYear(year: string): Promise<number | string> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    const y = year.trim();
    if (!/^\d{4}$/.test(y) || Number(y) < 1 || Number(y) > 9998) return 'Enter the fiscal year as YYYY.';
    const sid = this.session.sheetId()!;
    try {
      const made = await firstValueFrom(
        this.http.post<Period[]>(`${this.url(sid)}/generate-fiscal-year`, { year: Number(y) },
          { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => [...ps, ...made].sort(byFrom));
      return made.length;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not add periods.';
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter the fiscal year as YYYY.';
      return e instanceof HttpErrorResponse ? `Could not generate periods (${e.status}).` : 'Could not generate periods.';
    }
  }

  /** The fiscal year (FY<yyyy>) a date (YYYY-MM-DD) falls in, by the sheet's fiscal start month: named by the
   *  calendar year its first day falls in. */
  fiscalYearOf(date: string): string {
    const year = Number(date.slice(0, 4));
    const month = Number(date.slice(5, 7));
    return 'FY' + String(month >= this.session.fiscalStartMonth() ? year : year - 1).padStart(4, '0');
  }

  /** Close a period, fixing its due-total; an error message when refused. */
  async close(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(`${this.url(sid)}/${id}/close`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => ps.map((p) => (p.id === id ? period : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not close a period.';
      if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is already closed.';
      return e instanceof HttpErrorResponse ? `Could not close period (${e.status}).` : 'Could not close period.';
    }
  }

  /** Soft-close a period, fixing its figures while its claims can still change; an error message when
   *  refused. */
  async softClose(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(`${this.url(sid)}/${id}/soft-close`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => ps.map((p) => (p.id === id ? period : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not close a period.';
      if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is already closed.';
      return e instanceof HttpErrorResponse ? `Could not soft-close period (${e.status}).` : 'Could not soft-close period.';
    }
  }

  /** Reopen a closed or soft-closed period, making its due-total live again (a role the sheet allows); an error message when
   *  refused. */
  async reopen(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(`${this.url(sid)}/${id}/reopen`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => ps.map((p) => (p.id === id ? period : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not reopen a period.';
      if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is not closed.';
      return e instanceof HttpErrorResponse ? `Could not reopen period (${e.status}).` : 'Could not reopen period.';
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/periods`;
  }
}

function byFrom(a: Period, b: Period): number {
  return a.from.localeCompare(b.from);
}
import { Component, inject, signal } from '@angular/core';
import { Figures } from '../../core/figures';
import { Period, Periods } from '../../core/periods';

// The sheet's periods: one form adds a period, another generates one per calendar month, a third the twelve of a fiscal year,
// and the list shows each with its dates, its cap on each person's open claims in it, the fiscal year its from-date falls in, and its
// due-total, the due of the claims that count whose date falls in it (fixed once it is closed), and
// whether it is closed or soft-closed, with buttons to close it, soft-close it and reopen it (by the roles the sheet allows).
@Component({
  selector: 'app-periods',
  template: `
    <section aria-label="Periods" data-testid="periods">
      <h2>Periods</h2>
      <form (submit)="submit($event)" data-testid="period-form">
        <label for="period-form-name">Name</label>
        <input
          id="period-form-name"
          data-testid="period-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="period-form-from">From (YYYY-MM-DD)</label>
        <input
          id="period-form-from"
          data-testid="period-form-from"
          placeholder="YYYY-MM-DD"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="period-form-to">To (YYYY-MM-DD)</label>
        <input
          id="period-form-to"
          data-testid="period-form-to"
          placeholder="YYYY-MM-DD"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <label for="period-form-cap">Open claims cap per person (blank for none)</label>
        <input
          id="period-form-cap"
          data-testid="period-form-cap"
          inputmode="numeric"
          [value]="cap()"
          (input)="cap.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="period-form-submit" [disabled]="saving()">Add period</button>
        @if (error(); as err) {
          <p role="alert" data-testid="period-form-error">{{ err }}</p>
        }
      </form>
      <form (submit)="generate($event)" data-testid="period-generate-form">
        <label for="period-generate-from">Generate monthly periods from (YYYY-MM-DD)</label>
        <input
          id="period-generate-from"
          data-testid="period-generate-from"
          placeholder="YYYY-MM-DD"
          [value]="genFrom()"
          (input)="genFrom.set(value($event)); genError.set(null)"
        />
        <label for="period-generate-to">To (YYYY-MM-DD)</label>
        <input
          id="period-generate-to"
          data-testid="period-generate-to"
          placeholder="YYYY-MM-DD"
          [value]="genTo()"
          (input)="genTo.set(value($event)); genError.set(null)"
        />
        <button type="submit" data-testid="period-generate" [disabled]="generating()">Generate periods</button>
      </form>
      <form (submit)="generateFy($event)" data-testid="period-generate-fy-form">
        <label for="period-generate-fy-year">Generate the monthly periods of fiscal year (YYYY)</label>
        <input
          id="period-generate-fy-year"
          data-testid="period-generate-fy-year"
          inputmode="numeric"
          placeholder="YYYY"
          [value]="fyYear()"
          (input)="fyYear.set(value($event)); genError.set(null)"
        />
        <button type="submit" data-testid="period-generate-fy" [disabled]="generating()">Generate fiscal year</button>
      </form>
      @if (generated() !== null) {
        <p>Made <span data-testid="period-generated">{{ generated() }}</span> period(s)</p>
      }
      @if (genError(); as err) {
        <p role="alert" data-testid="period-generate-error">{{ err }}</p>
      }
      <table data-testid="period-list">
        <thead>
          <tr><th scope="col">Name</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Fiscal year</th><th scope="col">Due total</th><th scope="col">Closed</th><th scope="col">Cap</th><th scope="col">Actions</th></tr>
        </thead>
        <tbody>
          @for (p of periods.periods(); track p.id) {
            <tr [attr.data-testid]="'period-row-' + p.name">
              <th scope="row" data-testid="period-name">{{ p.name }}</th>
              <td data-testid="period-from">{{ p.from }}</td>
              <td data-testid="period-to">{{ p.to }}</td>
              <td data-testid="period-fy">{{ periods.fiscalYearOf(p.from) }}</td>
              <td data-testid="period-due-total">{{ p.closedTotal ?? dueTotals().get(p.id) ?? '0.00' }}</td>
              <td data-testid="period-closed">{{ p.closed ? 'yes' : p.soft ? 'soft' : 'no' }}</td>
              <td data-testid="period-cap">{{ p.cap ?? '' }}</td>
              <td>
                <button type="button" data-testid="period-close" [disabled]="acting() === p.id" (click)="close(p)">
                  Close<span class="visually-hidden"> period {{ p.name }}</span>
                </button>
                <button type="button" data-testid="period-soft-close" [disabled]="acting() === p.id" (click)="softClose(p)">
                  Soft-close<span class="visually-hidden"> period {{ p.name }}</span>
                </button>
                <button type="button" data-testid="period-reopen" [disabled]="acting() === p.id" (click)="reopen(p)">
                  Reopen<span class="visually-hidden"> period {{ p.name }}</span>
                </button>
                @if (actionError()?.id === p.id) {
                  <p role="alert" data-testid="period-error">{{ actionError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class PeriodsPanel {
  protected readonly periods = inject(Periods);
  protected readonly name = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly cap = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The generate form: its dates, how many it last made, and its refusal. */
  protected readonly genFrom = signal('');
  protected readonly genTo = signal('');
  protected readonly generating = signal(false);
  protected readonly generated = signal<number | null>(null);
  protected readonly genError = signal<string | null>(null);
  /** The fiscal year typed for the fiscal-year generator, which shares the count and refusal above. */
  protected readonly fyYear = signal('');
  /** The period whose action is under way, and the last action's refusal, by period. */
  protected readonly acting = signal<number | null>(null);
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

  /** Each open period's live due-total, by period id (a closed one shows the total fixed when it was
   *  closed). */
  protected readonly dueTotals = inject(Figures).periodDueTotals;

  protected close(p: Period): Promise<void> {
    return this.act(p, () => this.periods.close(p.id));
  }

  protected softClose(p: Period): Promise<void> {
    return this.act(p, () => this.periods.softClose(p.id));
  }

  protected reopen(p: Period): Promise<void> {
    return this.act(p, () => this.periods.reopen(p.id));
  }

  private async act(p: Period, action: () => Promise<string | null>): Promise<void> {
    if (this.acting() !== null) return;
    this.actionError.set(null);
    this.acting.set(p.id);
    try {
      const err = await action();
      if (err) this.actionError.set({ id: p.id, message: err });
    } finally {
      this.acting.set(null);
    }
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async generate(e: Event): Promise<void> {
    e.preventDefault();
    if (this.generating()) return;
    this.generated.set(null);
    this.genError.set(null);
    this.generating.set(true);
    try {
      const made = await this.periods.generate(this.genFrom(), this.genTo());
      if (typeof made === 'string') this.genError.set(made);
      else this.generated.set(made);
    } finally {
      this.generating.set(false);
    }
  }

  protected async generateFy(e: Event): Promise<void> {
    e.preventDefault();
    if (this.generating()) return;
    this.generated.set(null);
    this.genError.set(null);
    this.generating.set(true);
    try {
      const made = await this.periods.generateFiscalYear(this.fyYear());
      if (typeof made === 'string') this.genError.set(made);
      else this.generated.set(made);
    } finally {
      this.generating.set(false);
    }
  }

  protected async submit(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
